const input = $input.first().json;
const body = input.body ?? input;
const extracao = body.extracao ?? {};

const submission_id = String(body.submission_id ?? "").trim();
const correct_answer = String(body.correct_answer ?? "").trim();

const enunciado = String(extracao.enunciado ?? "").trim();
const desenvolvimento_aluno = String(extracao.desenvolvimento_aluno ?? "").trim();
const resposta_aluno = String(extracao.resposta_aluno ?? "").trim();
const legibilidade = String(extracao.legibilidade ?? "").trim();
const confianca_extracao = Number(extracao.confianca_extracao ?? 0);
const observacoes_extracao = String(extracao.observacoes ?? "").trim();

function normalizarResposta(valor) {
  return String(valor ?? "")
    .trim()
    .replace(",", ".")
    .replace(/[^\d.-]/g, "");
}

const resposta_aluno_normalizada = normalizarResposta(resposta_aluno);
const correct_answer_normalizada = normalizarResposta(correct_answer);

const resposta_correta =
  resposta_aluno_normalizada !== "" &&
  resposta_aluno_normalizada === correct_answer_normalizada;

const tipo_prompt = resposta_correta
  ? "resposta_correta"
  : "resposta_incorreta";

const entrada_valida = Boolean(
  submission_id &&
  correct_answer &&
  enunciado &&
  resposta_aluno
);

const prompt_base = `
Você é um Sistema Tutor Inteligente para matemática do Ensino Fundamental 1.

Dados da questão:
- Enunciado: ${enunciado}
- Resposta correta esperada: ${correct_answer}
- Desenvolvimento do aluno: ${desenvolvimento_aluno || "não informado"}
- Resposta final do aluno: ${resposta_aluno || "não informada"}
- Legibilidade da extração: ${legibilidade || "não informada"}
- Confiança da extração: ${confianca_extracao}
- Observações da extração: ${observacoes_extracao || "nenhuma"}

Regras gerais:
1. Não invente informações.
2. Use linguagem adequada para criança do Ensino Fundamental 1 no feedback do aluno.
3. O feedback do professor pode ser um pouco mais técnico, mas deve ser objetivo.
4. Retorne APENAS JSON válido.
5. Não use markdown.
6. Não use crases.
`;

const prompt_resposta_correta = `
${prompt_base}

A resposta final do aluno está CORRETA.

Sua tarefa:
- Confirmar que o aluno acertou.
- Explicar de forma simples por que a resposta está correta.
- Reforçar positivamente o raciocínio.
- Se o desenvolvimento estiver incompleto, mencione isso de forma leve para o professor, sem penalizar o aluno.
- Sugerir uma próxima ação para consolidar o aprendizado.

Formato obrigatório:
{
  "acertou": true,
  "status_avaliacao": "correta",
  "tipo_erro": "nenhum",
  "resumo_erro": "",
  "feedback_aluno": "",
  "feedback_professor": "",
  "dica_proxima_acao": "",
  "confianca_feedback": 0.95
}
`;

const prompt_resposta_incorreta = `
${prompt_base}

A resposta final do aluno está INCORRETA.

Sua tarefa:
- Explicar o erro provável de forma simples.
- Identificar se o problema parece ser de cálculo, interpretação, procedimento incompleto, resposta ausente ou outro.
- Não dar um feedback punitivo.
- Ajudar o aluno a perceber o caminho correto.
- Sugerir uma próxima ação para o professor trabalhar esse erro.

Use estes valores:
- status_avaliacao: "incorreta", "parcial" ou "indefinida"
- tipo_erro: "calculo", "interpretacao", "procedimento_incompleto", "resposta_ausente", "extracao_duvidosa" ou "outro"

Formato obrigatório:
{
  "acertou": false,
  "status_avaliacao": "incorreta",
  "tipo_erro": "",
  "resumo_erro": "",
  "feedback_aluno": "",
  "feedback_professor": "",
  "dica_proxima_acao": "",
  "confianca_feedback": 0.90
}
`;

const prompt_feedback = resposta_correta
  ? prompt_resposta_correta
  : prompt_resposta_incorreta;

return [
  {
    json: {
      timestamp: new Date().toISOString(),
      submission_id,
      correct_answer,
      correct_answer_normalizada,
      enunciado,
      desenvolvimento_aluno,
      resposta_aluno,
      resposta_aluno_normalizada,
      resposta_correta,
      tipo_prompt,
      legibilidade,
      confianca_extracao,
      observacoes_extracao,
      entrada_valida,
      prompt_feedback,
      provedor_ia: "gemini",
      modelo_feedback: "gemini"
    }
  }
];

const original = $('Preparar dados').first().json;
const aiOutput = $input.first().json;

function getText(value) {
  if (!value) return "";

  if (typeof value === "string") {
    return value;
  }

  if (Array.isArray(value)) {
    return value.map(getText).filter(Boolean).join("\n");
  }

  if (typeof value === "object") {
    const priorityKeys = [
      "text",
      "output",
      "response",
      "content",
      "message",
      "result"
    ];

    for (const key of priorityKeys) {
      if (value[key]) {
        const found = getText(value[key]);
        if (found) return found;
      }
    }

    if (value.candidates?.[0]?.content?.parts) {
      return getText(value.candidates[0].content.parts);
    }
  }

  return "";
}

function extractJson(raw) {
  if (!raw) return null;

  let cleaned = String(raw)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");

  if (start === -1 || end === -1 || end <= start) {
    return null;
  }

  const jsonText = cleaned.slice(start, end + 1);

  try {
    return JSON.parse(jsonText);
  } catch (error) {
    return null;
  }
}

const raw_ai_response = getText(aiOutput);
const feedback = extractJson(raw_ai_response);

const parse_ok = feedback !== null;

const respostaCorreta =
  String(original.resposta_aluno).trim() === String(original.correct_answer).trim();

const acertou =
  typeof feedback?.acertou === "boolean"
    ? feedback.acertou
    : respostaCorreta;

const status_avaliacao =
  feedback?.status_avaliacao ??
  (respostaCorreta ? "correta" : "indefinida");

const tipo_erro =
  feedback?.tipo_erro ??
  (respostaCorreta ? "nenhum" : "outro");

const resumo_erro = feedback?.resumo_erro ?? "";

const feedback_aluno =
  feedback?.feedback_aluno ??
  (respostaCorreta
    ? "Muito bem! Sua resposta está correta."
    : "Não foi possível gerar um feedback personalizado agora.");

const feedback_professor =
  feedback?.feedback_professor ??
  (parse_ok
    ? ""
    : "A IA não retornou um JSON válido. Verifique a resposta bruta da IA no log.");

const dica_proxima_acao =
  feedback?.dica_proxima_acao ??
  (respostaCorreta
    ? "Propor uma questão parecida para reforçar o aprendizado."
    : "Revisar o raciocínio do aluno e tentar novamente com mediação.");

const confianca_feedback = Number(feedback?.confianca_feedback ?? 0);

const ok = parse_ok && Boolean(feedback_aluno) && Boolean(feedback_professor);

const status_n8n = ok
  ? "feedback_gerado_com_sucesso"
  : "erro_feedback_ia";

const resposta_backend = {
  ok,
  submission_id: original.submission_id,
  fluxo: "geracao_feedback",
  status_n8n,
  provedor_ia: original.provedor_ia,
  modelo: original.modelo_feedback,
  avaliacao: {
    acertou,
    status_avaliacao,
    tipo_erro,
    resumo_erro,
    feedback_aluno,
    feedback_professor,
    dica_proxima_acao,
    confianca_feedback
  },
  entrada: {
    correct_answer: original.correct_answer,
    enunciado: original.enunciado,
    desenvolvimento_aluno: original.desenvolvimento_aluno,
    resposta_aluno: original.resposta_aluno,
    legibilidade: original.legibilidade,
    confianca_extracao: original.confianca_extracao,
    observacoes_extracao: original.observacoes_extracao
  },
  erro: ok ? null : {
    parse_ok,
    mensagem: parse_ok
      ? "Feedback incompleto retornado pela IA."
      : "A resposta da IA não contém JSON válido."
  }
};

return [
  {
    json: {
      timestamp: original.timestamp,
      submission_id: original.submission_id,
      correct_answer: original.correct_answer,
      enunciado: original.enunciado,
      desenvolvimento_aluno: original.desenvolvimento_aluno,
      resposta_aluno: original.resposta_aluno,
      legibilidade: original.legibilidade,
      confianca_extracao: original.confianca_extracao,
      observacoes_extracao: original.observacoes_extracao,

      parse_ok,
      ok,
      status_n8n,
      provedor_ia: original.provedor_ia,
      modelo: original.modelo_feedback,

      acertou,
      status_avaliacao,
      tipo_erro,
      resumo_erro,
      feedback_aluno,
      feedback_professor,
      dica_proxima_acao,
      confianca_feedback,

      raw_ai_response,
      resposta_backend_json: JSON.stringify(resposta_backend),
      resposta_backend
    }
  }
];
